style.css:
@-moz-document domain("docin.com") {
/* 隐藏加入我的组合 */
    .addcomdocs,
    div.addcomdocs.addcomdocs-on {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        width: 0 !important;
        height: 0 !important;
        overflow: hidden !important;
    }

    /* 隐藏编辑区域 */
    div.editable_outer,
    div.editable_outer div.editable {
        display: none !important;
    }

    /* 隐藏广告区域 */
    div.adBox {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        width: 0 !important;
        height: 0 !important;
        overflow: hidden !important;
    }

    /* 隐藏底部导航区域 */
    div.nav_end_bd.nav_end_sty2 {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        width: 0 !important;
        height: 0 !important;
        overflow: hidden !important;
    }

    /* 隐藏固定顶部工具栏 */
    div.doc_hd_mini.fixed_header_tool {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        width: 0 !important;
        height: 0 !important;
        overflow: hidden !important;
    }

    /* 隐藏阅读工具栏外层 */
    div.reader_tools_bar_wrap {
        display: none !important;
        visibility: hidden !important;
    }

    /* 隐藏阅读工具栏内层 */
    div.reader_tools_bar_wrap div.tools_bottom_bar {
        display: none !important;
        visibility: hidden !important;
    }
}
